import hashlib
import base64

def verify(token: str) -> bool:
    secret = os.environ.get('API_SECRET')
    if not secret:
        raise ValueError('API_SECRET environment variable is not set')
    # Assuming the token is a base64 encoded HMAC
    try:
        decoded_token = base64.b64decode(token).decode('utf-8')
        token_parts = decoded_token.split(':')
        if len(token_parts) != 2:
            return False
        token_signature, token_data = token_parts
        expected_signature = hmac.new(secret.encode(), token_data.encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(token_signature, expected_signature)
    except Exception:
        return False

